LogicDefinition.ScriptText:
#load "reference"
using System.Collections.Generic;
using System.Linq;
using FS.SDK.Util;
using System.Threading;
using System;
using FS.SDK;

 List<Char> ReadList = new List<Char>();

 if(SIM_IsDetecting)
 {
 	if(FillReadList())
    	WriteReadData();
 }


//Leseablauf
if(IO_OUT_Operation_Read_Request)
{
	Logger.I("IO_OUT_Operation_Read_Request");

	IO_IN_Busy_BUSY = true;
	SIM_DoRead = true;

	if(SIM_ReadOk) //Lesen IO
	{  
	   timer+=SceneObject.DeltaTime;
	   if(timer<1f)
	   return;
		Logger.I("SIM_ReadOk");
		FillReadList();
		IO_IN_Completion_Read_Complete = true;
		IO_IN_Operation_Read_Result_Code = 0; //Wertüberprüfen
		IO_IN_Match_AIM_DPM_Grade = 4; //mit 4-A keine probleme

		timer=0;
		/*
		//max String größe anpassen
		if(ReadList.Count >= 30)
			IO_IN_Read_Data_Result_Data_Size = 30;
		else*/
			IO_IN_Read_Data_Result_Data_Size = (ushort)ReadList.Count;
		WriteReadData();
	}
	else if(SIM_ReadError) //Lesen n.IO
	{ timer+=SceneObject.DeltaTime;
       if(timer<1f)
       return;
		Logger.I("SIM_ReadError");
	 	IO_IN_Error_Read_Failure = true;
	 	IO_IN_Completion_Read_Complete = true;
	 	IO_IN_Operation_Read_Result_Code = 1; //Wertüberprüfen
	 	timer=0;
	}
}

if(IO_OUT_Completion_Read_Complete_Clear) //Lesen abgeschlossen, Werte zurücksetzen
{   timer+=SceneObject.DeltaTime;
       if(timer<1f)
       return;
	Logger.I("IO_OUT_Completion_Read_Complete_Clear");
	IO_IN_Busy_BUSY = false;
	SIM_DoRead = false;
	IO_IN_Error_Read_Failure = false;
	IO_IN_Completion_Read_Complete = false;
	IO_IN_Match_AIM_DPM_Grade = 0;
	IO_IN_Operation_Read_Result_Code = 0;
	timer=0;
}

if(IO_OUT_Operation_Tune_Request) //Tuning starten
{   timer+=SceneObject.DeltaTime;
       if(timer<1f)
       return;
	IO_IN_Busy_BUSY = true;
	IO_IN_Match_AIM_DPM_Grade = 4;

	//IO_IN_Error_Tune_Failure = true;
	IO_IN_Completion_Tune_Complete = true;
	timer=0;
}

if(IO_OUT_Completion_Tune_Complete_Clear) //Tuning abgeschlossen
{   timer+=SceneObject.DeltaTime;
       if(timer<1f)
       return;
	IO_IN_Busy_BUSY = false;
	IO_IN_Completion_Tune_Complete = false;
	timer=0;
	//IO_IN_Error_Tune_Failure = false;
}

//Hilfsmethoden
bool FillReadList()
{
	//string aufsplitten und readList befüllen
	if(!String.IsNullOrWhiteSpace(SIM_ReadData))
	{
		ReadList = SIM_ReadData.ToList();
		return true;
	}
	else
	{
		return false;
	}

}

